using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Threading;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using MemeManager;
using D=System.Drawing;

class SmokeTests {
 static int assertions;
 static void Check(bool condition,string name){if(!condition)throw new Exception("FAIL: "+name);Console.WriteLine("PASS: "+name);assertions++;}
 static object Invoke(object target,string name,params object[] args){return target.GetType().GetMethod(name,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(target,args);}
 static T Field<T>(object target,string name){return (T)target.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(target);}
 [STAThread] static int Main(string[] args){try{Run(args[0]);Console.WriteLine(assertions+" assertions passed.");return 0;}catch(Exception ex){Console.Error.WriteLine(ex);return 1;}}
 static void Run(string root){
  Directory.CreateDirectory(root);Check(!StoragePaths.IsOnC(StoragePaths.Resolve(new string[0])),"default storage resolves outside C");Check(StoragePaths.Resolve(new[]{"--data-dir",root})==Path.GetFullPath(root),"explicit non-C data directory is honored");bool rejected=false;try{StoragePaths.Resolve(new[]{"--data-dir","C:\\MemeManager-test"});}catch(IOException){rejected=true;}Check(rejected,"C drive data location is rejected before writing");string tempRoot=StoragePaths.Initialize(new[]{"--data-dir",Path.Combine(root,"storage-check")});Check(Environment.GetEnvironmentVariable("TEMP")==Path.Combine(tempRoot,"temp")&&!StoragePaths.IsOnC(Path.GetTempPath()),"process temporary paths are redirected outside C");Check(StoragePaths.ExportDirectory(root).StartsWith(Path.Combine(root,"processed")),"default processing output stays with non-C data");string inputs=Path.Combine(root,"inputs");Directory.CreateDirectory(inputs);Directory.CreateDirectory(Path.Combine(inputs,"nested"));
  string[] captions={"今天也要开心","收到！","让我想想","快乐加倍","好耶","先喝杯茶"};string[] colors={"#EED9BB","#B8D8D1","#D5C8DF","#F1CBBC","#CEDCAE","#C6D5E8"};
  for(int i=0;i<captions.Length;i++)using(var bitmap=new D.Bitmap(240,210))using(var g=D.Graphics.FromImage(bitmap))using(var font=new D.Font("Microsoft YaHei",15)){
   g.Clear(D.ColorTranslator.FromHtml(colors[i]));g.SmoothingMode=D.Drawing2D.SmoothingMode.AntiAlias;g.FillEllipse(D.Brushes.White,75,35,90,90);g.FillEllipse(D.Brushes.Black,99,67,7,10);g.FillEllipse(D.Brushes.Black,135,67,7,10);g.DrawArc(new D.Pen(D.Color.FromArgb(60,90,70),3),108,78,25,20,0,180);g.DrawString(captions[i],font,D.Brushes.DarkSlateGray,25,152);bitmap.Save(Path.Combine(inputs,captions[i]+".png"),D.Imaging.ImageFormat.Png);
  }
  File.Copy(Path.Combine(inputs,captions[0]+".png"),Path.Combine(inputs,"nested","duplicate.png"),true);File.WriteAllText(Path.Combine(inputs,"broken.gif"),"not an image");
  string gifHex="47494638396101000100800000000000FFFFFF21F904000A0000002C000000000100010000020244010021F904000A0000002C00000000010001000002024C01003B";
  byte[] gif=Enumerable.Range(0,gifHex.Length/2).Select(i=>Convert.ToByte(gifHex.Substring(i*2,2),16)).ToArray();File.WriteAllBytes(Path.Combine(inputs,"小小动图.gif"),gif);
  var library=new Library(Path.Combine(root,"library"));var result=library.Import(new[]{inputs},"test-group",new HashSet<string>(),CancellationToken.None,n=>{});
  Check(result.Items.Count==7,"folder import includes valid PNG and animated GIF");Check(result.Duplicates==1,"nested duplicate detected");Check(result.Errors==1,"corrupt GIF rejected without interrupting import");Check(result.Items.All(x=>x.GroupId=="test-group"),"import assigns current group");
  library.Data.Memes.AddRange(result.Items);library.Data.Groups.Add(new Group{Id="test-group",Name="日常快乐"});library.Save();
  var importedGif=result.Items.Single(x=>x.Extension==".gif");Check(File.ReadAllBytes(library.FileFor(importedGif)).SequenceEqual(gif),"GIF original bytes preserved");
  using(var stream=File.OpenRead(library.FileFor(importedGif))){Check(new GifBitmapDecoder(stream,BitmapCreateOptions.None,BitmapCacheOption.OnLoad).Frames.Count==2,"animated GIF has two frames");}
  var again=library.Import(new[]{inputs},null,new HashSet<string>(result.Items.Select(x=>x.Id)),CancellationToken.None,n=>{});Check(again.Items.Count==0&&again.Duplicates==8,"reimport skips previously stored images");
  var cancellation=new CancellationTokenSource();cancellation.Cancel();Check(library.Import(new[]{inputs},null,new HashSet<string>(),cancellation.Token,n=>{}).Cancelled,"import cancellation");
  library.Data.Memes[0].Uses=12;library.Data.Memes[0].Favorite=true;library.Data.Memes[0].LastUsed=DateTime.Now;library.Save();var loaded=new Library(library.Root);Check(loaded.Data.Memes[0].Uses==12&&loaded.Data.Memes[0].Favorite,"usage and favorite persistence");Check(loaded.Data.Groups[0].Name=="日常快乐","group persistence");
  var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};var manager=new ManagerWindow();manager.Initialize(new[]{"--background","--smoke-test","--data-dir",library.Root});var window=Field<Window>(manager,"window");var cards=Field<WrapPanel>(manager,"cards");Check(cards.Children.Count==0,"background startup defers image decoding");
  Check(Field<Window>(manager,"picker")==null,"picker is created lazily");Invoke(manager,"Settings");var settings=Field<Window>(manager,"settingsWindow");Check(settings.IsVisible&&!window.IsVisible&&settings.Owner==null,"settings opens independently without showing manager");Invoke(manager,"Settings");Check(object.ReferenceEquals(settings,Field<Window>(manager,"settingsWindow")),"settings window reuses its existing instance");
  object[] hotkeyArgs={Field<IntPtr>(manager,"handle"),0x312,new IntPtr(1),IntPtr.Zero,false};manager.GetType().GetMethod("MessageHook",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(manager,hotkeyArgs);
  var picker=Field<Window>(manager,"picker");picker.UpdateLayout();Invoke(manager,"RenderPicker");Check((bool)hotkeyArgs[4]&&picker.IsVisible&&!window.IsVisible&&settings.IsEnabled,"global hotkey opens only picker while settings remains usable");Check(picker.Owner==null&&!picker.ShowInTaskbar,"picker has its own independent tool window");
  Render(picker,Path.Combine(root,"preview-picker.png"));Render(settings,Path.Combine(root,"preview-settings.png"));
  var pickerSearch=Field<TextBox>(manager,"pickerSearch");pickerSearch.Text="今天";Invoke(manager,"RefreshPicker");Check(Field<List<Meme>>(manager,"pickerItems").Count==1,"picker search filters independently");var pickerCards=Field<WrapPanel>(manager,"pickerCards");Check(((Border)pickerCards.Children[0]).ContextMenu==null,"picker cards do not expose management actions");
  var liveForCopy=Field<Library>(manager,"library");int priorUses=liveForCopy.Data.Memes[0].Uses;Invoke(manager,"CompleteCopy",liveForCopy.Data.Memes[0],picker);Check(!picker.IsVisible&&settings.IsVisible&&!window.IsVisible&&liveForCopy.Data.Memes[0].Uses==priorUses+1,"successful selection records usage and hides only picker");
  pickerSearch.Clear();Invoke(manager,"Show");window.UpdateLayout();Invoke(manager,"RenderMore");Check(cards.Children.Count==7&&window.IsEnabled,"manager remains usable alongside modeless settings");
  var search=Field<TextBox>(manager,"search");search.Text="今天";Invoke(manager,"Refresh");Check(cards.Children.Count==1,"name search filters cards");search.Clear();Invoke(manager,"Refresh");
  Check(Field<List<Meme>>(manager,"visible")[0].Uses==priorUses+1,"default sort prioritizes usage frequency");
  var playerImage=new Image{Source=BitmapFrame.Create(new Uri(library.FileFor(importedGif)))};var player=new GifPlayer(playerImage,library.FileFor(importedGif));player.Start();player.Stop();Check(playerImage.Source!=null,"GIF player starts and restores thumbnail");
  Render(window,Path.Combine(root,"preview.png"));var preferences=Field<Library>(manager,"library").Data.Settings;preferences.Palette="深夜墨";Invoke(manager,"ApplyTheme");Invoke(manager,"Refresh");Render(window,Path.Combine(root,"preview-dark.png"));Check(((SolidColorBrush)window.Resources["Canvas"]).Color.ToString()=="#FF17211E","dark palette applied");
  // Exercise the same DataObject image + file representations without touching the user's clipboard.
  var data=new DataObject();data.SetFileDropList(new System.Collections.Specialized.StringCollection{library.FileFor(importedGif)});data.SetImage((BitmapSource)playerImage.Source);Check(data.ContainsFileDropList()&&data.ContainsImage(),"clipboard payload supports original file and image");
  var live=Field<Library>(manager,"library");var originals=live.Data.Memes.ToList();for(int i=0;i<2000;i++)live.Data.Memes.Add(new Meme{Id=originals[0].Id,Extension=originals[0].Extension,Name="额外表情 "+i,Added=DateTime.Now});Invoke(manager,"Refresh");window.UpdateLayout();Invoke(manager,"RenderMore");Check(cards.Children.Count<65,"large library keeps a bounded number of visual cards");
  var scroller=(ScrollViewer)window.FindName("Scroller");scroller.ScrollToEnd();window.UpdateLayout();Invoke(manager,"RenderMore");Check(Field<int>(manager,"firstRendered")>1900,"virtualized grid reaches end of large library");
  Invoke(manager,"TogglePicker");picker.UpdateLayout();Invoke(manager,"RenderPicker");Check(pickerCards.Children.Count<45,"picker uses bounded cards for large library");var pickerScroll=Field<ScrollViewer>(manager,"pickerScroll");pickerScroll.ScrollToEnd();picker.UpdateLayout();Invoke(manager,"RenderPicker");Check(Field<int>(manager,"pickerFirst")>1900,"picker can browse end of large library");Invoke(manager,"TogglePicker");Check(!picker.IsVisible&&window.IsVisible&&settings.IsVisible&&pickerCards.Children.Count==0,"hotkey hides picker without hiding manager or settings and releases its cards");settings.Close();Check(Field<Window>(manager,"settingsWindow")==null,"closing settings clears its independent instance");
  window.Hide();Check(cards.Children.Count==0&&Field<Dictionary<string,BitmapSource>>(manager,"thumbnails").Count==0,"hiding releases cards and thumbnail references");
  live.Data.Memes=originals;
  string fresh=Path.Combine(root,"处理结果.png");using(var bitmap=new D.Bitmap(3,2)){bitmap.SetPixel(0,0,D.Color.Magenta);bitmap.Save(fresh,D.Imaging.ImageFormat.Png);}
  string requestId=ImportBridge.Submit(live.Root,new[]{fresh,library.FileFor(originals[0]),Path.Combine(root,"已移走.png")},"test-group");Invoke(manager,"ProcessPendingImports");PumpUntil(()=>ImportBridge.ReadResponse(live.Root,requestId)!=null);var response=ImportBridge.ReadResponse(live.Root,requestId);Check(response.Imported==1&&response.Duplicates==1&&response.Failed==1&&string.IsNullOrEmpty(response.Error),"processed batch import reports added, duplicate and missing output files");Check(live.Data.Memes.Last().GroupId=="test-group"&&new Library(live.Root).Data.Memes.Count==8,"processed import uses selected group and persists through manager");ImportBridge.Acknowledge(live.Root,requestId);
  string retryId=ImportBridge.Submit(live.Root,new[]{fresh},null);Invoke(manager,"ProcessPendingImports");PumpUntil(()=>ImportBridge.ReadResponse(live.Root,retryId)!=null);var retry=ImportBridge.ReadResponse(live.Root,retryId);Check(retry.Imported==0&&retry.Duplicates==1&&live.Data.Memes.Count==8,"retrying processed import never duplicates library entries");ImportBridge.Acknowledge(live.Root,retryId);Check(ImportBridge.Next(live.Root)==null,"completed import requests leave no pending work");
  Invoke(manager,"Exit");
  File.WriteAllText(Path.Combine(library.Root,"library.json"),"broken");var recovered=new Library(library.Root);Check(recovered.LoadWarning!=null&&recovered.Data.Memes.Count==7,"corrupt primary recovers from atomic backup");
 }
 static void PumpUntil(Func<bool> predicate){var frame=new System.Windows.Threading.DispatcherFrame();var watch=System.Diagnostics.Stopwatch.StartNew();var timer=new System.Windows.Threading.DispatcherTimer{Interval=TimeSpan.FromMilliseconds(15)};timer.Tick+=(s,e)=>{if(predicate()||watch.Elapsed>TimeSpan.FromSeconds(10))frame.Continue=false;};timer.Start();System.Windows.Threading.Dispatcher.PushFrame(frame);timer.Stop();if(!predicate())throw new TimeoutException("Import response did not arrive.");}
 static void Render(Window window,string file){window.UpdateLayout();var content=(FrameworkElement)window.Content;int width=(int)Math.Ceiling(content.ActualWidth),height=(int)Math.Ceiling(content.ActualHeight);var drawing=new DrawingVisual();using(var context=drawing.RenderOpen()){context.DrawRectangle(window.Background,null,new Rect(0,0,width,height));context.DrawRectangle(new VisualBrush(content),null,new Rect(0,0,width,height));}var bitmap=new RenderTargetBitmap(width,height,96,96,PixelFormats.Pbgra32);bitmap.Render(drawing);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using(var stream=File.Create(file))encoder.Save(stream);}
}
